<script setup lang="ts">
import {computed,onMounted,onUnmounted,ref,watch} from 'vue';
import {onBeforeRouteLeave} from 'vue-router';
import {api,ApiError} from '../lib/api';
import {bestiaryIssues,type BestiaryCatalog,type BestiaryData,type BestiaryRecord,type BestiarySummary} from '../../../api/src/campaign-bestiary-model';
import CampaignCreatureSheet from './CampaignCreatureSheet.vue';
const props=defineProps<{campaignId:string;archived?:boolean;selectable?:boolean;selectedIds?:string[];selectionFull?:boolean}>();
const emit=defineEmits<{(e:'select',creature:BestiarySummary):void;(e:'dirty',value:boolean):void}>();
const catalog=ref<BestiaryCatalog|null>(null),creatures=ref<BestiarySummary[]>([]),hasMore=ref(false),query=ref(''),showArchived=ref(false),loading=ref(false),busy=ref(false),error=ref(''),notice=ref('');
const creator=ref(false),mode=ref<'quick'|'custom'>('quick'),realm=ref<'realite'|'verite'>('realite'),difficultyId=ref('standard'),archetypeId=ref('combattant'),weaponGroup=ref('Pistolet léger'),count=ref(1),drafts=ref<{id:string;data:BestiaryData}[]>([]),editing=ref<BestiaryRecord|null>(null),viewed=ref<BestiaryRecord|null>(null),baseline=ref('');
const endpoint=`/api/campaigns/${props.campaignId}/bestiary`;
const dirty=computed(()=>drafts.value.length>0&&(editing.value?JSON.stringify(drafts.value)!==baseline.value:true));
const valid=computed(()=>drafts.value.length>0&&drafts.value.every(row=>!bestiaryIssues(row.data).length));
let live=true,seq=0,detailSeq=0,timer:ReturnType<typeof setTimeout>|undefined;
function failure(e:unknown){const code=e instanceof Error?e.message:'';error.value=({creature_version_conflict:'Cette créature a changé ailleurs. Tes modifications restent ici.',creature_creation_conflict:'Cette fiche existe déjà avec un contenu différent.',invalid_creature:'Vérifie les valeurs, l’arme et les capacités.',invalid_bestiary_generator:'Choisis un archétype et une arme compatibles.'} as Record<string,string>)[code]||'Action impossible. Réessaie.';if(e instanceof ApiError&&[401,403,404].includes(e.status)){error.value='Bestiaire inaccessible avec ton compte.';creatures.value=[];}}
async function load(more=false){const n=++seq;loading.value=true;try{const r=await api<{creatures:BestiarySummary[];hasMore:boolean}>(`${endpoint}?q=${encodeURIComponent(query.value.trim())}&archived=${showArchived.value}&offset=${more?creatures.value.length:0}`);if(n===seq&&live){creatures.value=more?[...creatures.value,...r.creatures.filter(a=>!creatures.value.some(b=>a.id===b.id))]:r.creatures;hasMore.value=r.hasMore;}}catch(e){if(n===seq&&live)failure(e);}finally{if(n===seq)loading.value=false;}}
async function start(){try{catalog.value=await api<BestiaryCatalog>(endpoint+'/catalog');await load();}catch(e){failure(e);}}
function discard(){return !dirty.value||window.confirm('Abandonner les créatures ou modifications non enregistrées ?');}
function create(next:'quick'|'custom'){if(!discard())return;mode.value=next;drafts.value=[];viewed.value=null;editing.value=null;creator.value=true;error.value='';notice.value='';}
function chooseRealm(next:'realite'|'verite'){realm.value=next;archetypeId.value=catalog.value?.archetypes.find(a=>a.realm===next)?.id||'';weaponGroup.value='Aucune';}
function request(){return {seed:crypto.randomUUID(),count:mode.value==='quick'&&!props.selectable?count.value:1,difficultyId:difficultyId.value,archetypeId:archetypeId.value,weaponGroup:realm.value==='realite'?weaponGroup.value:'Aucune'};}
async function generate(){if(busy.value||!discard())return;busy.value=true;error.value='';try{const r=await api<{creatures:BestiaryData[]}>(endpoint+'/generate',{method:'POST',body:JSON.stringify(request())});if(!live)return;const rows=r.creatures.map(data=>({id:crypto.randomUUID(),data}));if(mode.value==='custom'){const d=rows[0].data;d.name='Nouvelle créature';d.description='';d.hook='';d.abilities=[];d.weaknesses=[];d.tags=[];}
  drafts.value=rows;editing.value=null;creator.value=false;viewed.value=null;notice.value=mode.value==='quick'?'Fiche prête pour la scène. Conserve-la, rejette-la ou regénère. Rien n’est encore enregistré.':'';
 }catch(e){if(live)failure(e);}finally{busy.value=false;}}
function reject(){drafts.value=[];editing.value=null;creator.value=false;notice.value='Fiche rejetée, rien n’a été enregistré.';}
function regenerate(){drafts.value=[];void generate();}
async function save(){if(busy.value||!valid.value)return;busy.value=true;error.value='';try{const selected=mode.value==='quick'&&props.selectable&&drafts.value.length===1?drafts.value[0]:null;if(editing.value)await api(`${endpoint}/${editing.value.id}`,{method:'PATCH',body:JSON.stringify({data:drafts.value[0].data,version:editing.value.version,archived:editing.value.archived})});else await api(endpoint,{method:'POST',body:JSON.stringify({creatures:drafts.value})});if(!live)return;notice.value=`${drafts.value.length} créature(s) enregistrée(s).`;drafts.value=[];editing.value=null;creator.value=false;showArchived.value=false;query.value='';await load();if(selected&&!props.selectionFull){const d=selected.data;emit('select',{id:selected.id,name:d.name,realm:d.realm,difficultyId:d.difficultyId,role:d.role,version:1,archived:false});}}catch(e){if(live)failure(e);}finally{busy.value=false;}}
async function open(summary:BestiarySummary,edit=false,copy=false){if(!discard())return;const n=++detailSeq;busy.value=true;error.value='';try{const r=await api<{creature:BestiaryRecord}>(`${endpoint}/${summary.id}`);if(!live||n!==detailSeq)return;creator.value=false;drafts.value=[];editing.value=null;if(edit||copy){mode.value='custom';const d=structuredClone(r.creature.data);if(copy)d.name=(d.name+' · copie').slice(0,120);drafts.value=[{id:copy?crypto.randomUUID():summary.id,data:d}];editing.value=copy?null:r.creature;baseline.value=JSON.stringify(drafts.value);viewed.value=null;}else viewed.value=r.creature;}catch(e){if(live&&n===detailSeq)failure(e);}finally{busy.value=false;}}
async function archive(summary:BestiarySummary){if(busy.value||!discard()||!window.confirm(summary.archived?'Réactiver cette créature ?':'Archiver cette créature ? Les scènes existantes restent consultables.'))return;busy.value=true;try{const r=await api<{creature:BestiaryRecord}>(`${endpoint}/${summary.id}`);await api(`${endpoint}/${summary.id}`,{method:'PATCH',body:JSON.stringify({data:r.creature.data,version:r.creature.version,archived:!summary.archived})});drafts.value=[];viewed.value=null;await load();}catch(e){failure(e);}finally{busy.value=false;}}
function beforeUnload(e:BeforeUnloadEvent){if(dirty.value||busy.value){e.preventDefault();e.returnValue='';}}
watch([query,showArchived],()=>{clearTimeout(timer);timer=setTimeout(()=>void load(),250);});watch(dirty,v=>emit('dirty',v),{immediate:true});
onBeforeRouteLeave(()=>discard());onMounted(()=>{void start();window.addEventListener('beforeunload',beforeUnload);});onUnmounted(()=>{live=false;seq++;detailSeq++;clearTimeout(timer);emit('dirty',false);window.removeEventListener('beforeunload',beforeUnload);});
</script>
<template>
 <section class="bestiary-manager" aria-label="Bestiaire de la campagne"><h3>Mes créatures de campagne</h3><div v-if="!archived" class="actions"><button class="primary" type="button" :disabled="busy||!catalog||selectionFull&&selectable" @click="create('quick')">Générateur de bestiaire</button><button type="button" :disabled="busy||!catalog" @click="create('custom')">Créer une créature</button></div><p v-if="error" role="alert">{{ error }}</p><p v-if="notice" role="status">{{ notice }}</p>
  <div v-if="creator&&catalog&&!archived" class="card"><h4>{{ mode==='quick'?'Générer une créature pour la scène':'Créer une fiche personnalisée' }}</h4><p>{{ mode==='quick'?'La fiche est jouable immédiatement. Tu décides ensuite si tu l’enregistres.':'Le bloc de combat proposé est indicatif et reste entièrement modifiable.' }}</p><div class="fields"><label>Monde<select :value="realm" @change="chooseRealm(($event.target as HTMLSelectElement).value as 'realite'|'verite')"><option value="realite">Réalité</option><option value="verite">Vérité</option></select></label><label>Difficulté<select v-model="difficultyId"><option v-for="d in catalog.difficulties" :key="d.id" :value="d.id">{{ d.name }} · {{ d.hint }}</option></select></label><label>Archétype<select v-model="archetypeId"><option v-for="a in catalog.archetypes.filter(a=>a.realm===realm)" :key="a.id" :value="a.id">{{ a.name }}</option></select></label><label v-if="realm==='realite'">Type d’arme<select v-model="weaponGroup"><option value="Aucune">Aucune / attaque naturelle</option><option v-for="g in [...new Set(catalog.weapons.map(w=>w.group))]" :key="g" :value="g">{{ g }}</option></select></label><label v-if="mode==='quick'&&!selectable">Nombre de créatures<input v-model.number="count" type="number" min="1" max="10" /></label></div><div class="actions"><button class="primary" type="button" :disabled="busy" @click="generate">{{ busy?'Création…':mode==='quick'?'Générer maintenant':'Ouvrir la fiche personnalisée' }}</button><button type="button" @click="creator=false">Annuler</button></div></div>
  <form v-if="drafts.length&&catalog&&!archived" @submit.prevent="save"><p>{{ mode==='quick'&&!editing?'Créature générée à la volée, encore non enregistrée.':'Ajuste la fiche puis enregistre-la.' }}</p><details v-for="(d,i) in drafts" :key="d.id" :open="i===0" class="card"><summary>{{ d.data.name }} · {{ catalog.difficulties.find(t=>t.id===d.data.difficultyId)?.name }}</summary><CampaignCreatureSheet v-model:data="d.data" :catalog="catalog" editable /></details><div class="actions"><button class="primary" :disabled="busy||!valid">{{ editing?'Enregistrer les modifications':mode==='quick'?'Conserver et enregistrer':'Enregistrer la créature' }}</button><button v-if="mode==='quick'&&!editing" type="button" :disabled="busy" @click="regenerate">Rejeter et regénérer</button><button v-if="mode==='quick'&&!editing" type="button" :disabled="busy" @click="reject">Rejeter cette fiche</button><button v-else type="button" @click="drafts=[]">Annuler les modifications</button></div></form>
  <div v-if="viewed&&catalog" class="card"><div class="actions"><strong>Fiche enregistrée{{ viewed.archived?' · Archivée':'' }}</strong><button type="button" @click="viewed=null">Fermer la fiche</button></div><CampaignCreatureSheet :data="viewed.data" :catalog="catalog" /></div>
  <label>Rechercher mes créatures<input v-model="query" type="search" maxlength="100" placeholder="Nom, rôle, difficulté…" /></label><label v-if="!selectable" class="check"><input v-model="showArchived" type="checkbox" />Afficher les créatures archivées</label><div class="list" role="region" aria-label="Liste des créatures de campagne"><p v-if="!loading&&!creatures.length">Aucune créature pour ces critères.</p><article v-for="c in creatures" :key="c.id" class="row"><div><strong>{{ c.name }}</strong><small>{{ c.realm==='realite'?'Réalité':'Vérité' }} · {{ catalog?.difficulties.find(d=>d.id===c.difficultyId)?.name }} · {{ c.role }}</small></div><div class="actions"><button v-if="selectable&&!c.archived" type="button" :disabled="busy||selectionFull||selectedIds?.includes(c.id)" @click="emit('select',c)">{{ selectedIds?.includes(c.id)?'Déjà dans la scène':'Ajouter '+c.name+' à la scène' }}</button><button type="button" @click="open(c)">Consulter {{ c.name }}</button><template v-if="!archived"><button type="button" @click="open(c,true)">Modifier {{ c.name }}</button><button type="button" @click="open(c,false,true)">Dupliquer</button><button type="button" @click="archive(c)">{{ c.archived?'Réactiver':'Archiver' }}</button></template></div></article><p v-if="loading" role="status">Chargement…</p><button v-if="hasMore" type="button" @click="load(true)">Voir d’autres créatures</button></div>
 </section>
</template>
<style scoped>
.bestiary-manager{display:grid;gap:16px;min-width:0;color:#eaf2ff}.bestiary-manager h3,.bestiary-manager h4{margin:0}.bestiary-manager p{line-height:1.6;color:#b5c8dc}.actions{display:flex;flex-wrap:wrap;gap:10px;align-items:center}.bestiary-manager label{display:grid;gap:7px}.bestiary-manager input:not([type=checkbox]),.bestiary-manager select{box-sizing:border-box;width:100%;min-width:0;min-height:44px;padding:10px;background:#08131f;color:#edf4ff;border:1px solid #405875;border-radius:6px;font:inherit}.bestiary-manager button{min-height:44px;padding:10px 14px;background:#101e30;color:#eaf2ff;border:1px solid #405875;border-radius:6px;cursor:pointer}.bestiary-manager button.primary{background:#a3eaff;color:#071725}.bestiary-manager button:disabled{opacity:.5;cursor:default}.fields{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:12px}.card{padding:16px;border:1px solid #405875;background:#0b1725;border-radius:6px}.card>summary{cursor:pointer;min-height:44px;margin-bottom:12px}.list{max-height:450px;overflow:auto;border:1px solid #405875;border-radius:6px;padding:12px}.row{display:grid;gap:8px;padding:12px;border-bottom:1px solid #304c62}.row small{display:block;color:#a3b7cc}.check{display:flex!important;align-items:center;gap:10px}.check input{width:20px;height:20px}button:focus-visible,input:focus-visible,select:focus-visible,summary:focus-visible{outline:2px solid #a3eaff;outline-offset:3px}@media(max-width:600px){.fields{grid-template-columns:1fr}.card{padding:10px}}
</style>
